const splitTopic=(id,labels)=>{const t=byId(id);if(!t||!t.sections?.[0])return;const ps=t.sections[0].content.match(/<p>[\s\S]*?<\/p>/g)||[t.sections[0].content];const groups=labels.map((label,i)=>({id:"ctf-"+id+"-"+(i+1),title:label,content:ps.slice(Math.floor(i*ps.length/labels.length),Math.floor((i+1)*ps.length/labels.length)).join("")||ps[i%ps.length]}));t.sections=groups;};
